import{_ as i,o as a,c as o,ae as t}from"./chunks/framework.1Lna8NcP.js";const h=JSON.parse('{"title":"API Keys & Integrations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api-keys-and-integrations.md","filePath":"guide/api-keys-and-integrations.md"}'),l={name:"guide/api-keys-and-integrations.md"};function n(s,e,r,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="api-keys-integrations" tabindex="-1">API Keys &amp; Integrations <a class="header-anchor" href="#api-keys-integrations" aria-label="Permalink to &quot;API Keys &amp; Integrations&quot;">​</a></h1><p>All integrations are optional. Libertas works locally without them.</p><h2 id="claude-api-key-optional" tabindex="-1">Claude API key (optional) <a class="header-anchor" href="#claude-api-key-optional" aria-label="Permalink to &quot;Claude API key (optional)&quot;">​</a></h2><p>Where to set:</p><ul><li><code>Settings</code> → <code>API Keys</code> → <code>Claude API key</code></li><li>Or environment variable <code>CLAUDE_API_KEY</code></li></ul><p>What it unlocks:</p><ul><li><code>Insights</code> chat (<code>POST /api/insights/chat</code>)</li><li>AI-assisted guidance features</li></ul><p>Behavior without key:</p><ul><li>Rule-based insights and planning still work</li><li>AI chat returns a not-configured message</li></ul><h2 id="news-api-key-optional" tabindex="-1">News API key (optional) <a class="header-anchor" href="#news-api-key-optional" aria-label="Permalink to &quot;News API key (optional)&quot;">​</a></h2><p>Where to set:</p><ul><li><code>Settings</code> → <code>API Keys</code> → <code>News API key</code></li><li>Or environment variable <code>NEWS_API_KEY</code></li></ul><p>What it unlocks:</p><ul><li>richer market/news coverage</li></ul><p>Behavior without key:</p><ul><li>dashboard news falls back to RSS/cached sources</li></ul><h2 id="plaid-optional" tabindex="-1">Plaid (optional) <a class="header-anchor" href="#plaid-optional" aria-label="Permalink to &quot;Plaid (optional)&quot;">​</a></h2><p>Where to set:</p><ul><li><code>Settings</code> → <code>API Keys</code> → Plaid <code>Client ID</code>, <code>Secret</code>, <code>Environment</code></li></ul><p>Relevant endpoints:</p><ul><li><code>/api/integrations/plaid/create-link-token</code></li><li><code>/api/integrations/plaid/exchange-public-token</code></li><li><code>/api/integrations/plaid/sync-now</code></li><li><code>/api/integrations/plaid/status</code></li></ul><p>Notes:</p><ul><li>Keep Plaid optional for users preferring CSV/manual-only workflows</li><li>Use <code>sandbox</code> first while validating behavior</li></ul><h2 id="google-sheets-csv-feeds-optional" tabindex="-1">Google Sheets CSV feeds (optional) <a class="header-anchor" href="#google-sheets-csv-feeds-optional" aria-label="Permalink to &quot;Google Sheets CSV feeds (optional)&quot;">​</a></h2><p>Libertas supports Sheets through CSV export URLs (no Google OAuth requirement).</p><p>Relevant endpoints:</p><ul><li><code>/api/integrations/sheets/validate-feed</code></li><li><code>/api/integrations/sheets/add-feed</code></li><li><code>/api/integrations/sheets/sync-now</code></li><li><code>/api/integrations/sheets/status</code></li></ul><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><ul><li>Keys stored via Settings are local to your machine (SQLite)</li><li>At-rest encryption support is documented in <a href="/Libertas/security.html">Security &amp; Encryption</a></li><li>For strongest control, use passphrase mode and store secrets in a local password manager</li></ul>',29)])])}const g=i(l,[["render",n]]);export{h as __pageData,g as default};
